    // Calculate the maximum number of possible arrangements
    double totalCombinations = 1;
    for (int i = 1; i <= n; i++) {
        totalCombinations *= i;
    }

    // Calculate the number of favorable arrangements
    double favorableCombinations = 1;
    for (int i = 1; i <= n; i++) {
